import {icon,logo,escapeHTML as e,safeImage as img,demoPhotos,fmtDay,fmtTime,timeLeft,extraDescription} from './visuals.js';
import {isDemo,currentSession,requireSession,signIn,register,confirmAccount,resendConfirmation,requestPasswordReset,completePasswordReset,signOut} from './auth.js';
import {getListings,getListing,myListings,createListing,updateListing,getInbox,getThread,sendMessage,getRating,addRating,getProfile,health} from './api.js';
const page=document.body.dataset.page||'home';const el=document.getElementById('app');
const params=new URLSearchParams(location.search);let session=null,allListings=[],allThreads=[],selectedThread=null,selectedListing=null,photoFile=null,score=0;
const internalPages=['dashboard','add-food','my-listings','messages','profile'];const authPages=['login','register','confirm-account','forgot-password','reset-password'];
function toast(message,error=false){let area=document.querySelector('.toast-area');if(!area){area=document.createElement('div');area.className='toast-area';area.setAttribute('role','status');area.setAttribute('aria-live','polite');document.body.append(area);}let div=document.createElement('div');div.className='toast '+(error?'toast--error':'');div.textContent=message;area.append(div);setTimeout(()=>div.remove(),5500);}
function notice(msg,type='info'){return `<div role="status" class="notice ${type}">${icon(type==='error'?'alert':'checkCircle',18)}${e(msg)}</div>`}
function header(){let authed=!!session;return `<div class="${isDemo()?'demo-banner':''}">${isDemo()?`DESIGN PREVIEW · Example food listings and messages are not live. <a href="connection-check.html">Connection guide</a>`:''}</div><header class="site-header" id="siteHeader"><div class="container head-inner"><a class="brand" href="index.html" aria-label="ShareBite home">${logo()}</a><nav class="main-nav" id="nav" aria-label="Main navigation"><a class="${page==='home'?'active':''}" href="index.html">Home</a><a class="${page==='browse'?'active':''}" href="browse.html">Explore food</a><a class="${page==='how-it-works'?'active':''}" href="how-it-works.html">How it works</a><a class="${page==='privacy'?'active':''}" href="privacy.html">Our commitment</a>${authed?`<a class="${internalPages.includes(page)?'active':''}" href="dashboard.html">Dashboard</a>`:''}</nav><div class="header-actions">${authed?`<a class="user-chip" href="profile.html"><span class="avatar">${e((session.claims.name||session.claims.email||'M').slice(0,1).toUpperCase())}</span><span class="hide-sm">My account</span></a>`:`<a href="login.html" class="btn btn-light">Sign in</a><a href="register.html" class="btn btn-primary">Get started ${icon('arrowUp',16)}</a>`}<button id="menuBtn" class="menu-button" aria-label="Toggle navigation" aria-expanded="false">${icon('menu',21)}</button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand brand--white" href="index.html">${logo(true)}</a><p class="footer-desc">A little extra can mean a lot. Bringing good food and good people together, one shared meal at a time.</p><span class="pill" style="background:#275542;color:#d9edd3;border-color:#3e755b">${icon('leaf',13)} Inspired by SDG 2 · Zero Hunger</span></div><div><h4>Discover</h4><a href="browse.html">Browse food</a><a href="how-it-works.html">How it works</a><a href="register.html">Become a member</a></div><div><h4>Your space</h4><a href="dashboard.html">Dashboard</a><a href="add-food.html">Share food</a><a href="messages.html">Messages</a></div><div><h4>Good to know</h4><a href="privacy.html">Privacy & safety</a><a href="faq.html">Help & FAQs</a><a href="forgot-password.html">Reset password</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ShareBite. Built as a university cloud-computing prototype.</span><span>No phone numbers on public listings. <a href="privacy.html">Our approach ${icon('arrowUp',13)}</a></span></div></div></footer>`;}
function sidebar(){const links=[['grid','dashboard.html','Overview','dashboard'],['search','browse.html','Find food','browse'],['plus','add-food.html','Share food','add-food'],['bag','my-listings.html','My listings','my-listings'],['message','messages.html','Messages','messages'],['user','profile.html','Profile','profile']];return `<aside class="sidebar"><a class="brand brand--white" href="index.html">${logo(true)}</a><div class="sidebar-label">Workspace</div>${links.map(([i,u,n,k])=>`<a class="side-link ${page===k?'active':''}" href="${u}">${icon(i,19)} ${n}</a>`).join('')}<div class="side-bottom"><a href="privacy.html" class="side-link">${icon('shield',18)} Privacy & safety</a><button class="side-link" id="logout" style="width:100%;background:none;border:0;text-align:left">${icon('logout',18)} Sign out</button></div></aside>`;}
function shell(content,{dashboard=false,footerVisible=true}={}){el.innerHTML=header()+(dashboard?`<div class="dashboard-shell">${sidebar()}<main class="dash-main" id="main">${content}</main></div>`:`<main id="main">${content}</main>`)+(footerVisible?footer():'');globalEvents();initReveal();}
function intro(){let seenIntro=false;try{seenIntro=!!sessionStorage.getItem('sharebite-intro-seen')}catch{} if(page!=='home'||seenIntro||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const div=document.createElement('div');div.className='intro';div.id='intro';div.setAttribute('role','status');div.setAttribute('aria-label','ShareBite loading animation');div.innerHTML=`<div><div class="intro-scene"><span class="orbit-particle p1"></span><span class="orbit-particle p2"></span><span class="orbit-particle p3"></span><div class="intro-ring"></div><div class="intro-ring r2"></div><div class="intro-aura"></div><div class="intro-leaf l1">${icon('leaf',25)}</div><div class="intro-leaf l2">${icon('leaf',34)}</div><div class="intro-leaf l3">${icon('spark',17)}</div><div class="courier">${crateSVG(true)}</div></div><div class="intro-title">Share<span>Bite</span>.</div><div class="intro-caption">More than food. A shared future.</div><div class="intro-progress" aria-hidden="true"></div></div><button id="introSkip" class="intro-skip">Skip intro</button>`;document.body.append(div);document.body.classList.add('noscroll');let close=()=>{if(!div.isConnected)return;try{sessionStorage.setItem('sharebite-intro-seen','1')}catch{} div.classList.add('hide');document.body.classList.remove('noscroll');setTimeout(()=>div.remove(),900)};let timer=setTimeout(close,3700);document.getElementById('introSkip').onclick=()=>{clearTimeout(timer);close();};}
function crateSVG(character=false){return `<svg viewBox="0 0 470 470" role="img" aria-label="Illustrated basket of rescued fresh food"><defs><linearGradient id="box" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#f3cb8e"/><stop offset="1" stop-color="#ca915b"/></linearGradient><linearGradient id="tomato" x1="0" x2="1"><stop stop-color="#fc9c65"/><stop offset="1" stop-color="#db6750"/></linearGradient><linearGradient id="lime"><stop stop-color="#a5bf6c"/><stop offset="1" stop-color="#4e8752"/></linearGradient></defs><g transform="translate(5,3)"><ellipse cx="231" cy="414" rx="150" ry="24" fill="#2f654866"/><path d="M96 203c-17-60-5-99 19-118 42 30 47 70 21 121M130 209c-14-86 34-137 68-143 13 69-4 115-45 151M256 196c1-85 52-137 102-135 0 80-29 123-88 144" fill="#447c56"/><path d="M128 182c-14-57 18-105 49-116 16 54-1 95-30 122" fill="#79a767"/><path d="M270 187c28-58 72-80 122-70-9 54-52 79-105 83" fill="#a0b76f"/><path d="M160 171c-10-67 10-110 58-126 23 68 9 122-43 148" fill="#c2d08c"/><g stroke="#c5d79c" stroke-width="3" fill="none"><path d="M111 107c21 29 30 56 27 91M187 91c-22 38-24 72-28 103M319 89c-23 37-35 69-35 102"/></g><ellipse cx="166" cy="207" rx="70" ry="65" fill="url(#tomato)"/><ellipse cx="286" cy="203" rx="74" ry="68" fill="#eaa75e"/><ellipse cx="223" cy="168" rx="62" ry="66" fill="#d85f47"/><path d="M208 108c-4-27 11-36 29-40-2 19-10 33-29 40M204 112c-25-19-29-29-16-44 17 4 26 17 27 39" fill="#44764c"/><path d="M142 141c-16-18-22-31-17-43 19 0 33 17 38 41M288 139c5-31 19-43 38-41 4 18-9 32-30 46" fill="#6c995b"/><circle cx="356" cy="228" r="45" fill="#dfbe5c"/><path d="M347 188c-7-19-1-30 17-34 5 21-1 31-17 34" fill="#62864d"/><g transform="translate(76 215)"><path d="M17 0H296L272 167H45Z" fill="url(#box)" stroke="#c7905e" stroke-width="4"/><path d="M17 0H296L290 41H23Z" fill="#dba66c"/><path d="M50 51 67 151M99 50l8 104M155 50v104M206 50l-9 104M260 50l-18 104" stroke="#b67e4e" stroke-width="9" opacity=".58"/><path d="M27 20h260M38 114h241" stroke="#eac195" stroke-width="6" opacity=".58"/></g>${character?`<g><circle cx="172" cy="212" r="5" fill="#653c33"/><circle cx="196" cy="212" r="5" fill="#653c33"/><path d="M176 227q9 9 18-1" stroke="#653c33" stroke-width="3" fill="none" stroke-linecap="round"/></g>`:''}</g></svg>`;}
function tile(x){const name=e(x.foodName),category=e(x.category||'Food sharing'),where=e(x.location||'Collection area'),date=x.expiryTime?timeLeft(x.expiryTime):'Flexible';return `<article class="card food-card" data-reveal><a href="food-details.html?id=${encodeURIComponent(x.listingId)}" aria-label="View ${name}"><div class="food-card__media"><img loading="lazy" src="${img(x.imageUrl)}" onerror="this.onerror=null;this.src='assets/food-fallback.svg'" alt="${name}"><span class="pill">${icon('leaf',13)} ${category}</span></div></a><div class="food-card__body"><div class="food-card__meta">${icon('map',15)} ${where}</div><h3>${name}</h3><div class="food-card__meta">${icon('clock',15)} ${e(date)} <span style="margin-left:auto">${icon('bag',14)} ${e(x.quantity||'Available')}</span></div><div class="food-card__foot"><span class="muted">Shared with care</span><a class="link-arrow" href="food-details.html?id=${encodeURIComponent(x.listingId)}">See details ${icon('arrow',16)}</a></div></div></article>`;}
function hero(){return `<section class="hero"><div class="container"><div class="hero-copy"><span class="hero-tag"><span class="dot"></span> A more thoughtful way to share</span><h1>Good food.<br>Better <span class="serif-italic">together.</span></h1><p class="hero-text">Make every extra meal count. A beautifully simple place to share surplus food, discover what’s nearby and bring communities closer—without sharing your phone number.</p><div class="hero-buttons"><a class="btn btn-primary btn-lg" href="browse.html">Explore available food ${icon('arrowUp',19)}</a><a class="btn btn-light btn-lg" href="add-food.html">Share your food ${icon('arrow',18)}</a></div><div class="hero-proof"><div class="proof-avatars" aria-hidden="true"><span>A</span><span>J</span><span>M</span></div><span>Made for kind neighbours, local kitchens<br>and everyday food heroes.</span></div></div><div class="hero-stage" aria-hidden="true"><span class="hero-art-tag">GOOD FOOD IN MOTION</span><span class="orbit-particle p1"></span><span class="orbit-particle p2"></span><span class="orbit-particle p3"></span><div class="hero-orb"></div><div class="food-stage">${crateSVG()}</div><span class="deco-star s1">${icon('spark',25)}</span><span class="deco-star s2">${icon('spark',16)}</span><div class="floating-note n1"><span class="note-icon">${icon('heart',22)}</span><span><strong>Food worth sharing</strong><small>More meals. Less waste.</small></span></div><div class="floating-note n2"><span class="note-icon gold">${icon('bag',21)}</span><span><strong>Find food nearby</strong><small>Local collection made easier.</small></span></div><div class="floating-note n3">${icon('leaf',16)} <strong style="font-size:.72rem">Fresh possibilities</strong></div></div></div></section>`;}
function home(){shell(hero()+`<div class="hero-bottom"><div class="container ticker"><span>${icon('shield',17)} Sign in with Cognito</span><span>${icon('message',17)} Message within ShareBite</span><span>${icon('camera',17)} Photo-rich food listings</span><span>${icon('heart',17)} Built around community</span></div></div><div class="studio-marquee"><div class="container studio-marquee-inner"><span><b>✳</b> Thoughtfully shared</span><span><b>↗</b> Community-powered</span><span><b>✦</b> Privacy-minded</span><span><b>♡</b> Less food waste</span></div></div><section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">The ShareBite way</span><h2>Sharing can be <span class="serif-italic">beautifully simple.</span></h2></div><p class="muted">The thoughtful details that make giving and receiving food feel a little easier.</p></div><div class="feature-grid"><div class="card feature" data-reveal><span class="feature-icon">${icon('bag',27)}</span><h3>Share more, waste less</h3><p>Turn the food you won't use into something meaningful. Create detailed listings in just a few steps.</p></div><div class="card feature" data-reveal><span class="feature-icon">${icon('map',27)}</span><h3>Discover what's nearby</h3><p>Browse food shared in your area, with clear collection details, quantities and expiry information.</p></div><div class="card feature" data-reveal><span class="feature-icon">${icon('message',27)}</span><h3>Connect with confidence</h3><p>Arrange collection using in-platform messaging. No public phone number is needed.</p></div></div></div></section><section class="section section-soft"><div class="container"><div class="section-head"><div><span class="eyebrow">Fresh from the community</span><h2>There's good to <span class="serif-italic">go around.</span></h2></div><a class="btn btn-outline" href="browse.html">Explore all food ${icon('arrowUp',17)}</a></div><div id="homeFood" class="food-grid">${placeholderCards(3)}</div>${!isDemo()?`<p class="fine-print" style="margin-top:20px">Live listings require a ShareBite account. <a class="text-link" href="login.html?next=browse.html">Sign in to browse</a>.</p>`:''}</div></section><section class="section"><div class="container story"><div class="story-image" data-reveal><img loading="lazy" src="${demoPhotos.produce}" onerror="this.onerror=null;this.src='assets/food-fallback.svg'" alt="Fresh produce displayed for sharing"><div class="story-stat"><strong>Every meal</strong><span class="muted mini">can make a difference.</span></div></div><div data-reveal><span class="eyebrow">A community-first idea</span><h2>Small acts.<br><span class="serif-italic">Lasting impact.</span></h2><p class="muted">ShareBite is a Coventry University cloud-computing prototype inspired by UN Sustainable Development Goal 2. It's designed to make local redistribution easier—not to replace established food-safety guidance or professional aid services.</p><ul><li>${icon('checkCircle',20)} Clear allergy, storage and collection information</li><li>${icon('checkCircle',20)} A safer way to contact food donors</li><li>${icon('checkCircle',20)} Flexible tools for individuals and local providers</li></ul><a class="btn btn-primary" href="how-it-works.html">Discover how it works ${icon('arrow',17)}</a></div></div></section><section class="section-tight"><div class="container"><div class="cta-band" data-reveal><div><span class="eyebrow" style="color:#c4d8be">Your next good deed</span><h2>Have a little extra? <span class="serif-italic" style="color:#f4ca88">Share the good.</span></h2><p>Give surplus food a new story, one community connection at a time.</p></div><a class="btn btn-gold btn-lg" href="add-food.html">List your food ${icon('arrowUp',19)}</a></div></div></section>`);intro();let box=document.getElementById('homeFood');if(isDemo()){box.innerHTML=(awaitSafeDemo()).slice(0,3).map(tile).join('');initReveal();}else{box.innerHTML=`<div class="card" style="grid-column:1/-1;padding:36px;text-align:center">${icon('lock',27)}<h3 style="margin:12px 0">Sign in to discover shared food</h3><p class="muted">Your new backend protects live food listings.</p><a href="login.html?next=browse.html" class="btn btn-primary">Sign in to browse</a></div>`;}}
function awaitSafeDemo(){return [
{listingId:'demo-01',foodName:'Farm-fresh vegetable basket',category:'Fruit & vegetables',imageUrl:demoPhotos.produce,location:'Coventry city centre',quantity:'2 baskets',expiryTime:new Date(Date.now()+172800000).toISOString()},
{listingId:'demo-02',foodName:'Fresh artisan sourdough',category:'Bakery',imageUrl:demoPhotos.bakery,location:'Coventry CV1',quantity:'6 loaves',expiryTime:new Date(Date.now()+86400000).toISOString()},
{listingId:'demo-03',foodName:'Colourful lunch bowls',category:'Prepared meals',imageUrl:demoPhotos.meals,location:'Birmingham B5',quantity:'4 meals',expiryTime:new Date(Date.now()+57600000).toISOString()}];}
function placeholderCards(n){return Array.from({length:n},()=>'<div class="card-skeleton"></div>').join('');}
function pageHero(label,title,desc,buttons=''){return `<section class="page-hero"><div class="container"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${desc}</p>${buttons?`<div class="page-actions">${buttons}</div>`:''}</div></section>`;}
function authGuard(message='Please sign in to access this area.'){shell(pageHero('Member access','A little more <span class="serif-italic">connected.</span>',message,`<a class="btn btn-primary" href="login.html?next=${encodeURIComponent(location.pathname.split('/').pop()+location.search)}">Sign in ${icon('arrow',17)}</a><a class="btn btn-light" href="register.html">Create account</a>`)+`<div class="container" style="min-height:170px"></div>`);}
async function browse(){if(!session&&!isDemo())return authGuard('Sign in to view live food listings and arrange collection securely.');shell(pageHero('Community marketplace','Discover food, <span class="serif-italic">share joy.</span>','Explore local surplus food with clear details and direct in-platform messaging.',`<a class="btn btn-primary" href="add-food.html">${icon('plus',17)} Share something</a>`)+`<section class="layout"><div class="container"><div class="toolbar"><label class="search-wrap" aria-label="Search food">${icon('search',21)}<input id="foodSearch" type="search" placeholder="Search food, location or donor..." aria-label="Search food listings"></label><select id="foodCategory" class="input-select" aria-label="Filter by category"><option value="">All categories</option>${['Fruit & vegetables','Fruit and vegetables','Bakery','Prepared meals','Dairy','Pantry','Other'].map(c=>`<option>${c}</option>`).join('')}</select><select id="foodSort" class="input-select" aria-label="Sort by"><option value="new">Recently shared</option><option value="expiry">Expiring soon</option></select></div><div id="browseCount" class="results-count">Finding available food...</div><div id="foodGrid" class="food-grid">${placeholderCards(6)}</div></div></section>`);try{allListings=await getListings();drawBrowse();}catch(err){document.getElementById('foodGrid').innerHTML=empty('Couldn’t load food listings',err.message,'login.html','Sign in / retry');document.getElementById('browseCount').textContent='';}}
function drawBrowse(){let q=(document.getElementById('foodSearch')?.value||'').toLowerCase(),cat=document.getElementById('foodCategory')?.value||'',sort=document.getElementById('foodSort')?.value||'new';let items=allListings.filter(x=>(!cat||x.category===cat)&&[x.foodName,x.location,x.donorName,x.description].some(s=>String(s||'').toLowerCase().includes(q)));items.sort((a,b)=>sort==='expiry'?new Date(a.expiryTime)-new Date(b.expiryTime):new Date(b.createdAt)-new Date(a.createdAt));document.getElementById('browseCount').textContent=items.length+' food '+(items.length===1?'listing':'listings')+(isDemo()?' · Example data':' · Loaded from your API');document.getElementById('foodGrid').innerHTML=items.length?items.map(tile).join(''):empty('Nothing in this collection yet','Try another search or share a listing to get things going.','add-food.html','Share food');initReveal();}
function empty(title,desc,href,label){return `<div class="empty" style="grid-column:1/-1"><span class="empty-icon">${icon('leaf',32)}</span><h3>${e(title)}</h3><p>${e(desc)}</p>${href?`<a class="btn btn-primary" href="${href}">${e(label)} ${icon('arrow',17)}</a>`:''}</div>`;}
async function details(){let id=params.get('id');if(!id)return location.replace('browse.html');if(!session&&!isDemo())return authGuard('Sign in to see complete details for available food.');shell(pageHero('Shared with care','Every listing has <span class="serif-italic">a story.</span>','Get the details and arrange collection directly with a donor.')+`<section class="layout"><div class="container"><a class="btn-text" href="browse.html">${icon('back',16)} Back to discover</a><div id="detail" style="margin-top:25px">${placeholderCards(2)}</div></div></section>`);try{selectedListing=await getListing(id);if(!selectedListing)throw Error('This listing is not available.');const d=extraDescription(selectedListing.description);let own=session?.claims.sub===selectedListing.ownerUserId;let rating={count:0,average:null};try{rating=await getRating(id);}catch{}let dhtml=`<div class="detail-grid"><div><div class="detail-hero"><img src="${img(selectedListing.imageUrl)}" onerror="this.onerror=null;this.src='assets/food-fallback.svg'" alt="${e(selectedListing.foodName)}"></div><div class="detail-content"><span class="eyebrow">A thoughtful share</span><h2>What's included</h2><p>${e(d.description)}</p>${d['Prepared on']||d['Pickup window']||d.Dietary?`<h3>Additional details</h3><div class="detail-facts">${d['Prepared on']?`<div class="detail-fact">Food date<strong>${e(d['Prepared on'])}</strong></div>`:''}${d['Pickup window']?`<div class="detail-fact">Preferred collection<strong>${e(d['Pickup window'])}</strong></div>`:''}${d.Dietary?`<div class="detail-fact">Dietary notes<strong>${e(d.Dietary)}</strong></div>`:''}</div>`:''}<h3>Allergy information</h3><p>${e(selectedListing.allergyInfo||'Please confirm all ingredients and allergens directly with the donor.')}</p><h3>Storage guidance</h3><p>${e(selectedListing.storageInstructions||'Ask the donor for storage information.')}</p><div class="inline-alert">${icon('alert',18)} Food safety matters. Confirm ingredients, condition, storage and collection arrangements before accepting food.</div></div></div><aside><div class="card detail-card"><span class="pill">${e(selectedListing.category)}</span><h1>${e(selectedListing.foodName)}</h1><p class="muted">Shared by ${e(selectedListing.donorName?.includes('@')?'a ShareBite member':(selectedListing.donorName||'a community member'))}</p><div class="detail-facts"><div class="detail-fact">${icon('map',16)} Collection area<strong>${e(selectedListing.location)}</strong></div><div class="detail-fact">${icon('bag',16)} Quantity<strong>${e(selectedListing.quantity)}</strong></div><div class="detail-fact">${icon('calendar',16)} Collection deadline<strong>${e(fmtTime(selectedListing.expiryTime))}</strong></div><div class="detail-fact">${icon('clock',16)} Remaining<strong>${e(timeLeft(selectedListing.expiryTime))}</strong></div></div>${own?`<a href="my-listings.html" class="btn btn-primary" style="width:100%">Manage your listing ${icon('arrow',16)}</a>`:`<form id="messageDonorForm"><div class="form-group"><label for="hello">Send a private message</label><textarea class="field field-area" id="hello" maxlength="2000" required placeholder="Hi! Is this still available? I can collect after..." aria-label="Message donor"></textarea></div><button class="btn btn-primary" style="width:100%" type="submit">${icon('message',17)} Message the donor</button></form><p class="fine-print" style="text-align:center;margin-top:13px">No public phone number. Arrange collection in ShareBite.</p>`}${!own?`<div style="border-top:1px solid var(--line);margin-top:23px;padding-top:21px"><h3 style="font-size:1rem">Community feedback</h3><p class="muted mini">${rating.count?e(rating.average)+' / 5 from '+rating.count+' review(s)':'No ratings yet'} · Prototype feedback is not a verified collection record.</p><form id="ratingForm"><div class="rating-stars" id="stars" aria-label="Choose a rating">${[1,2,3,4,5].map(n=>`<button class="star-btn" aria-label="${n} stars" type="button" data-score="${n}">★</button>`).join('')}</div><button class="btn btn-light btn-small" style="margin-top:12px" type="submit">Submit feedback</button></form></div>`:''}</div></aside></div>`;document.getElementById('detail').innerHTML=dhtml;}catch(err){document.getElementById('detail').innerHTML=empty('We couldn’t find this listing',err.message,'browse.html','Browse food');}}
function addFood(){let tomorrow=new Date(Date.now()+3600e3);tomorrow.setMinutes(tomorrow.getMinutes()-tomorrow.getTimezoneOffset());shell(`<section class="page-hero page-hero--small"><div class="container"><span class="eyebrow">Give good food a new home</span><h1>Your extra could be <span class="serif-italic">their everything.</span></h1><p>Add clear details to help someone collect your food safely and easily.</p></div></section><section class="layout"><div class="container form-layout"><div class="card form-card"><div class="form-section-title">${icon('leaf',18)} Tell us about the food</div><form id="listingForm"><div class="form-grid"><div class="form-group"><label for="foodName">Food name <span class="required">*</span></label><input class="field" id="foodName" maxlength="120" required placeholder="e.g. Fresh vegetable basket"></div><div class="form-group"><label for="category">Category <span class="required">*</span></label><select class="field" id="category" required><option value="">Choose a category</option>${['Fruit & vegetables','Bakery','Prepared meals','Dairy','Pantry','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="form-group"><label for="description">Description <span class="required">*</span></label><textarea id="description" class="field field-area" maxlength="1300" required placeholder="Describe the food, ingredients, how it was prepared and anything helpful to know..."></textarea><span class="field-note">Be specific and honest about food condition and ingredients.</span></div><div class="form-grid"><div class="form-group"><label for="quantity">Available quantity <span class="required">*</span></label><input id="quantity" class="field" maxlength="80" required placeholder="e.g. 4 portions, 2 baskets"></div><div class="form-group"><label for="location">Collection area <span class="required">*</span></label><input id="location" class="field" maxlength="160" required placeholder="e.g. Coventry CV1 (not home address)"></div><div class="form-group"><label for="preparedOn">Food prepared / packaged on</label><input id="preparedOn" type="date" class="field"><span class="field-note">Optional; share if it helps recipients.</span></div><div class="form-group"><label for="expiryTime">Collection deadline <span class="required">*</span></label><input id="expiryTime" type="datetime-local" min="${tomorrow.toISOString().slice(0,16)}" required class="field"></div><div class="form-group"><label for="pickupWindow">Preferred pickup time</label><input id="pickupWindow" class="field" maxlength="80" placeholder="e.g. Today 16:00–18:00"></div><div class="form-group"><label for="dietary">Dietary notes</label><input id="dietary" class="field" maxlength="80" placeholder="e.g. Vegetarian (if confirmed)"></div></div><div class="form-group"><label for="allergyInfo">Allergy information <span class="required">*</span></label><textarea id="allergyInfo" class="field field-area" maxlength="1200" required placeholder="List known allergens and possible cross-contact. If unsure, say so explicitly."></textarea></div><div class="form-group"><label for="storageInstructions">Storage and handling</label><textarea id="storageInstructions" class="field field-area" maxlength="1000" placeholder="e.g. Refrigerate until collection. Keep chilled."></textarea></div><div class="form-section-title">${icon('camera',18)} Add a photograph</div><div class="upload-zone"><input id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"><input id="photoGallery" name="photoGallery" type="file" accept="image/jpeg,image/png,image/webp"><span class="upload-content">${icon('camera',35)}<strong>Add a beautiful photo of your food</strong><small style="margin-bottom:18px">JPG, PNG or WebP · Up to 5 MB</small><span style="display:flex;gap:10px;flex-wrap:wrap;justify-content:center"><label for="photo" class="btn btn-primary btn-small">${icon('camera',16)} Open camera</label><label for="photoGallery" class="btn btn-light btn-small">${icon('upload',16)} Choose from device</label></span></span><span class="upload-preview" id="photoPreview"><img id="photoImg" alt="Your selected food photograph preview"><label for="photoGallery" class="change">Change photo</label></span></div><p class="field-note" style="margin:11px 0 20px">Only upload photos you own or have permission to share. Your backend stores images privately.</p><div id="listingError"></div><button id="publishBtn" type="submit" class="btn btn-primary btn-lg">Publish your listing ${icon('arrowUp',18)}</button><p class="fine-print" style="margin:15px 0 0">Your name comes from your verified account. Your phone number is never requested.</p></form></div><aside><div class="card tips"><span class="pill">${icon('spark',14)} Thoughtful sharing</span><h3 style="margin-top:17px">The little details matter.</h3><ul><li>Share food you believe is suitable for redistribution.</li><li>Provide accurate ingredient and allergy information.</li><li>Use a general collection area; send precise collection details privately.</li><li>Clearly describe packaging, preparation and pickup deadlines.</li></ul><div class="inline-alert">${icon('shield',17)} ShareBite is a university prototype. You remain responsible for assessing food suitability and complying with applicable requirements.</div></div></aside></div></section>`,{dashboard:false});}
async function dashboard(){shell(`<div class="dash-top"><div><span class="eyebrow">Your ShareBite space</span><h1>Good to see you, <span class="serif-italic">${e((session.claims.name||'friend').split(' ')[0])}.</span></h1><p>Here's what your little corner of kindness looks like.</p></div><a class="btn btn-primary" href="add-food.html">${icon('plus',18)} Share some food</a></div><div class="stat-grid"><div class="card stat-card"><span class="stat-icon">${icon('bag',22)}</span><strong id="statMine">—</strong><small>My listings</small></div><div class="card stat-card"><span class="stat-icon">${icon('leaf',22)}</span><strong id="statAvailable">—</strong><small>Currently available</small></div><div class="card stat-card"><span class="stat-icon">${icon('message',22)}</span><strong id="statThreads">—</strong><small>Conversations</small></div></div><div class="dashboard-grid"><div class="card quick-card"><div class="subhead"><h3>Your latest listings</h3><a class="text-link" href="my-listings.html">View all ${icon('arrow',15)}</a></div><div id="latestListings">${placeholderCards(1)}</div></div><div class="card quick-card"><h3>Quick actions</h3><p class="muted mini">A little more good, in a few clicks.</p>${[['bag','Add a food listing','add-food.html'],['search','Find shared food','browse.html'],['message','Open messages','messages.html'],['user','Your profile','profile.html']].map(([i,t,u])=>`<a href="${u}" class="quick-action"><span class="feature-icon">${icon(i,21)}</span><strong style="font-size:.85rem">${t}</strong>${icon('chevron',16)}</a>`).join('')}</div></div>`,{dashboard:true,footerVisible:false});try{let [mine,inbox]=await Promise.all([myListings(),getInbox()]);document.getElementById('statMine').textContent=mine.length;document.getElementById('statAvailable').textContent=mine.filter(x=>x.status==='Available').length;document.getElementById('statThreads').textContent=inbox.length;document.getElementById('latestListings').innerHTML=mine.length?mine.slice(0,2).map(x=>`<a href="food-details.html?id=${encodeURIComponent(x.listingId)}" class="quick-action"><span class="feature-icon">${icon('bag',20)}</span><span><strong>${e(x.foodName)}</strong><span style="display:block;font-size:.75rem;color:#819585">${e(x.status)} · ${e(x.location)}</span></span>${icon('arrow',17)}</a>`).join(''):empty('Nothing shared just yet','Your first listing is only a few clicks away.','add-food.html','Share food');}catch(err){toast(err.message,true);}}
async function myFood(){shell(`<div class="dash-top"><div><span class="eyebrow">Your contributions</span><h1>My <span class="serif-italic">listings.</span></h1><p>Keep your shared food information up to date.</p></div><a href="add-food.html" class="btn btn-primary">${icon('plus',18)} Add food</a></div><div id="myFoodRows">${placeholderCards(2)}</div>`,{dashboard:true,footerVisible:false});try{let items=await myListings();document.getElementById('myFoodRows').innerHTML=items.length?`<div class="card" style="padding:20px">${items.map(x=>`<div class="quick-action" style="flex-wrap:wrap"><div class="avatar">${icon('bag',20)}</div><div style="flex:1;min-width:155px"><strong>${e(x.foodName)}</strong><div class="muted mini">${e(x.location)} · ${e(x.quantity)} · ${e(fmtDay(x.expiryTime))}</div></div><span class="status ${x.status==='Available'?'':x.status==='Reserved'?'status--amber':'status--grey'}">${e(x.status)}</span><select class="input-select status-select" aria-label="Update ${e(x.foodName)} status" data-id="${e(x.listingId)}"><option value="">Change status</option>${['Available','Reserved','Collected','Removed'].filter(y=>y!==x.status).map(y=>`<option>${y}</option>`).join('')}</select><a href="food-details.html?id=${encodeURIComponent(x.listingId)}" class="btn btn-light btn-small">View ${icon('arrow',14)}</a></div>`).join('')}</div>`:empty('Your first share starts here','Add a few details about food you would like to share.','add-food.html','Create a listing');}catch(err){document.getElementById('myFoodRows').innerHTML=empty('Unable to load listings',err.message,'dashboard.html','Back to dashboard');}}
function authVisual(){return `<aside class="auth-visual"><a class="brand brand--white" href="index.html">${logo(true)}</a><div><span class="eyebrow" style="color:#d6e3bc">Made for a kinder community</span><h2>It's good to <span class="serif-italic" style="color:#edc884">share.</span></h2><p>A little extra, a little kindness and a community looking out for one another.</p><div class="auth-photo"><img src="${demoPhotos.produce}" onerror="this.onerror=null;this.src='assets/food-fallback.svg'" alt="Fresh produce"></div></div><div class="mini" style="color:#bbd6c3">${icon('shield',16)} ${isDemo()?'Local design preview':'Account protection powered by Amazon Cognito'}</div></aside>`;}
function authFrame(label,title,desc,form,footerText){shell(`<div class="auth-wrap">${authVisual()}<section class="auth-panel"><div class="auth-content"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${desc}</p><div id="authAlert"></div>${form}<div class="auth-bottom">${footerText}</div>${isDemo()?`<p class="fine-print" style="text-align:center;margin-top:18px">Preview only: no real accounts, emails or password changes occur.</p>`:''}</div></section></div>`,{footerVisible:false});}
const emailField=(val='')=>`<div class="form-group"><label for="email">Email address</label><input class="field" id="email" type="email" autocomplete="email" value="${e(val)}" placeholder="you@example.com" required></div>`;
const passwordField=(id='password',autocomplete='current-password')=>`<div class="form-group"><label for="${id}">Password</label><div class="password-wrap"><input class="field" id="${id}" type="password" autocomplete="${autocomplete}" required minlength="${autocomplete==='new-password'?12:1}" placeholder="Enter your password"><button type="button" class="toggle-password" data-password="${id}">Show</button></div>${autocomplete==='new-password'?`<small class="field-note">Use 12+ characters, upper and lower case, a number and a symbol.</small>`:''}</div>`;
function authPage(){let val=params.get('email')||'';switch(page){case 'login':authFrame('Your account','Welcome <span class="serif-italic">back.</span>','Sign in to share food, explore listings and connect with the community.',`<form id="loginForm">${emailField(val)}${passwordField()}<div class="auth-meta"><span>Private, member-only access</span><a href="forgot-password.html" class="text-link">Forgot password?</a></div><button class="btn btn-primary btn-lg">Sign in ${icon('arrow',18)}</button></form>`,`New to ShareBite? <a href="register.html">Create an account</a>`);break;
case 'register':authFrame('Join the community',`Let's do some <span class="serif-italic">good.</span>`,'Create a free ShareBite account to share and discover food.',`<form id="registerForm"><div class="form-group"><label for="fullName">Your name</label><input class="field" id="fullName" required maxlength="100" autocomplete="name" placeholder="Your name"></div>${emailField()}${passwordField('password','new-password')}<div class="form-group"><label for="confirmPassword">Confirm password</label><input class="field" id="confirmPassword" type="password" autocomplete="new-password" minlength="12" required placeholder="Repeat your password"></div><button class="btn btn-primary btn-lg">Create account ${icon('arrowUp',18)}</button><p class="fine-print">By joining, you agree to share respectfully and review our <a href="privacy.html" class="text-link">privacy and safety guidance</a>.</p></form>`,`Already a member? <a href="login.html">Sign in</a>`);break;
case 'confirm-account':authFrame('One quick step','Verify your <span class="serif-italic">email.</span>','Enter the confirmation code sent by your account provider.',`<form id="confirmForm">${emailField(val)}<div class="form-group"><label for="verifyCode">Confirmation code</label><input id="verifyCode" class="field" inputmode="numeric" autocomplete="one-time-code" required placeholder="6-digit code"></div><button class="btn btn-primary btn-lg">Verify account ${icon('check',17)}</button></form><button id="resendBtn" class="btn-text" style="margin-top:17px">Resend confirmation code</button>`,`Already verified? <a href="login.html">Sign in</a>`);break;
case 'forgot-password':authFrame('Secure recovery','Reset your <span class="serif-italic">password.</span>','Enter your email to request a recovery code. Your password stays with Cognito.',`<form id="forgotForm">${emailField(val)}<button class="btn btn-primary btn-lg">Request recovery code ${icon('arrow',18)}</button></form>`,`Remembered it? <a href="login.html">Sign in</a>`);break;
case 'reset-password':authFrame('Almost there','A fresh <span class="serif-italic">start.</span>','Enter your recovery code and choose a new, strong password.',`<form id="resetForm">${emailField(val)}<div class="form-group"><label for="verifyCode">Recovery code</label><input class="field" id="verifyCode" required autocomplete="one-time-code" inputmode="numeric" placeholder="Verification code"></div>${passwordField('password','new-password')}<button class="btn btn-primary btn-lg">Set new password ${icon('check',17)}</button></form>`,`Back to <a href="login.html">sign in</a>`);break;}}
async function messages(){let maybe=params.get('listingId'),to=params.get('to');shell(`<div class="dash-top"><div><span class="eyebrow">Private, simple and in one place</span><h1>Your <span class="serif-italic">messages.</span></h1><p>Get the details directly from a donor, without sharing phone numbers.</p></div><a class="btn btn-light" href="browse.html">${icon('search',17)} Explore food</a></div><div class="message-layout"><aside class="thread-list"><div class="subhead" style="margin:2px 5px 17px"><h3 style="margin:0">Inbox</h3>${icon('message',20)}</div><div id="threads">Loading conversations...</div></aside><section class="thread-panel" id="conversation"><div class="chat-empty">${empty('A good conversation starts here','Choose a thread or browse food to message a donor.','browse.html','Find food')}</div></section></div><div class="inline-alert" style="margin-top:21px">${icon('shield',18)} Keep arrangements inside ShareBite and avoid sharing sensitive personal details. ${isDemo()?'Messages in preview mode stay in this browser only.':''}</div>`,{dashboard:true,footerVisible:false});try{allThreads=await getInbox();drawThreads();let chosen=params.get('threadId')||allThreads[0]?.threadId;if(chosen)await openThread(chosen);}catch(err){toast(err.message,true);document.getElementById('threads').innerHTML=`<p class="muted mini">${e(err.message)}</p>`;}}
function drawThreads(){let t=document.getElementById('threads');t.innerHTML=allThreads.length?allThreads.map(x=>`<button class="thread-item ${selectedThread===x.threadId?'active':''}" data-thread="${e(x.threadId)}"><span class="avatar">${icon('user',19)}</span><span style="min-width:0"><strong>${e(x.peerUserId?.startsWith('demo-')?'Community member':'ShareBite member')}</strong><small>${e(x.lastMessage||'New conversation')}</small></span></button>`).join(''):`<p class="muted mini">Your inbox is empty. Explore a listing and start a conversation.</p>`;}
async function openThread(id){selectedThread=id;drawThreads();const th=allThreads.find(x=>x.threadId===id);if(!th)return;let panel=document.getElementById('conversation');panel.innerHTML=`<div class="thread-head"><span class="avatar">${icon('message',19)}</span><div><strong>Conversation with a community member</strong><div class="muted mini">Messages stay inside ShareBite</div></div></div><div class="chat-messages" id="chatMessages">Loading messages...</div><form class="chat-send" id="threadSendForm"><label class="screen-reader" for="chatText">Write a message</label><input class="field" id="chatText" maxlength="2000" required placeholder="Write a thoughtful message..."><button class="btn btn-primary" type="submit" aria-label="Send message">${icon('arrow',20)}</button></form>`;try{let items=await getThread(id);document.getElementById('chatMessages').innerHTML=items.length?items.map(m=>`<div class="bubble ${m.senderUserId===session?.claims.sub?'mine':''}">${e(m.text)}<small>${e(fmtTime(m.sentAt))}</small></div>`).join(''):'<p class="muted mini center">No messages yet.</p>';document.getElementById('chatMessages').scrollTop=100000;}catch(err){toast(err.message,true);}}
async function profile(){shell(`<div class="dash-top"><div><span class="eyebrow">Your profile</span><h1>A familiar <span class="serif-italic">face.</span></h1><p>Your ShareBite account at a glance.</p></div></div><div id="profileContainer" class="card form-card" style="max-width:700px">Loading profile...</div>`,{dashboard:true,footerVisible:false});try{const x=await getProfile();document.getElementById('profileContainer').innerHTML=`<div class="avatar" style="width:64px;height:64px;font-size:1.4rem">${e((x.name||x.email||'M')[0].toUpperCase())}</div><h3 style="margin:18px 0 3px">${e(x.name||'ShareBite member')}</h3><p class="muted">${e(x.email||'')}</p><div class="detail-facts"><div class="detail-fact">Account protection<strong>Amazon Cognito${isDemo()?' (preview simulation)':''}</strong></div><div class="detail-fact">Public contact details<strong>Phone numbers not displayed</strong></div></div><div class="inline-alert">${icon('shield',18)} Profile information comes from your authentication account. Profile editing is not supported by this version of the backend.</div><a href="forgot-password.html?email=${encodeURIComponent(x.email||'')}" class="btn btn-light" style="margin-top:22px">${icon('lock',17)} Password recovery</a>`;}catch(err){toast(err.message,true);}}
function infoPage(which){let isHow=which==='how-it-works',isPrivacy=which==='privacy';let sections=isHow?[["01 / Share","Give surplus a new purpose","Create a detailed food listing with a clear photograph, collection area, quantity, allergens, storage guidance and deadline."],["02 / Discover","Find something wonderful","Explore available listings after signing in. Use search and category filters to find food you can collect."],["03 / Connect","Arrange it privately","Contact donors through ShareBite's internal inbox. Never publish phone numbers or private home addresses."],["04 / Complete","Keep listings up to date","Donors can mark items reserved, collected or removed. Ratings are prototype-level feedback and not verified transactions."]]:isPrivacy?[["Privacy by design","No public phone numbers","ShareBite's public listing form does not request contact numbers. Members coordinate collection using internal messages."],["Your account","Secure sign-in","Live account registration, email verification and password recovery use Amazon Cognito. Do not share your password or recovery codes."],["Images & information","Share safely","Uploaded photographs are private S3 objects served through temporary links by the backend. Avoid publishing private addresses, identifiable documents or sensitive details in food descriptions."],["Food safety","Your judgement matters","Donors should provide accurate food and allergen details. Collectors should verify condition and ingredients before accepting food. This university prototype is not a food-safety certification service."]]:[["Can I browse without an account?","The current deployed API requires authentication for live browsing. The public homepage remains available before sign-in."],["Is my phone number shared?","No phone-number field is needed. Arrange collection through ShareBite messages."],["Can I take a photo with my phone?","On supported phones, the add-food camera input can open your camera. JPG, PNG and WebP uploads are limited to 5 MB."],["How do I recover my password?","Use Forgot password. The live website sends a recovery request to Cognito and allows confirmation with the emailed code."],["Can I reserve food?","Donors can change a listing's status. The current backend does not yet include recipient-initiated reservations."],["Is ShareBite a production service?","No. It is a university prototype. Complete testing, operational controls and legal reviews are needed before real-world operation."]];shell(pageHero(isHow?'Our approach':isPrivacy?'Trust & safety':'Help centre',isHow?'Kindness made <span class="serif-italic">simple.</span>':isPrivacy?'Care, in every <span class="serif-italic">detail.</span>':'Answers for <span class="serif-italic">every step.</span>',isHow?'A few easy steps to connect surplus food with people who can use it.':isPrivacy?'Designed to help you share and connect more thoughtfully.':'Everything you need to know about using ShareBite.')+`<section class="layout"><div class="container" style="max-width:930px"><div style="display:grid;gap:17px">${sections.map(([n,t,d])=>`<div class="card" style="padding:29px 34px" data-reveal><span class="eyebrow">${e(n)}</span><h3 style="font-size:1.45rem;margin:10px 0 8px">${e(t)}</h3><p class="muted" style="margin:0">${e(d)}</p></div>`).join('')}</div><div style="margin-top:29px"><a class="btn btn-primary" href="browse.html">Explore food ${icon('arrow',18)}</a></div></div></section>`);}
function globalEvents(){document.getElementById('menuBtn')?.addEventListener('click',()=>{let nav=document.getElementById('nav'),b=document.getElementById('menuBtn');let opened=nav.classList.toggle('open');b.setAttribute('aria-expanded',String(opened));});document.getElementById('logout')?.addEventListener('click',async()=>{await signOut();location.href='index.html';});window.addEventListener('scroll',()=>document.getElementById('siteHeader')?.classList.toggle('scrolled',scrollY>20),{passive:true});}
function initReveal(){let nodes=document.querySelectorAll('[data-reveal]:not(.visible)');if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){nodes.forEach(n=>n.classList.add('visible'));return;}let obs=new IntersectionObserver(entries=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');obs.unobserve(en.target)}})},{threshold:.07});nodes.forEach(n=>obs.observe(n));}
function authError(message,type='error'){let n=document.getElementById('authAlert');if(n)n.innerHTML=notice(message,type);else toast(message,type==='error');}
function isStrong(pass){return pass.length>=12&&/[a-z]/.test(pass)&&/[A-Z]/.test(pass)&&/[0-9]/.test(pass)&&/[^A-Za-z0-9]/.test(pass);}
async function formSubmit(event){let f=event.target;if(!f.matches('form'))return;event.preventDefault();let btn=f.querySelector('[type=submit]');if(btn)btn.disabled=true;try{
 switch(f.id){case 'loginForm':await signIn(f.email.value.trim(),f.password.value);location.assign(params.get('next')||'dashboard.html');break;
 case 'registerForm':if(f.password.value!==f.confirmPassword.value)throw Error('The passwords do not match.');if(!isDemo()&&!isStrong(f.password.value))throw Error('Use 12+ characters with uppercase, lowercase, number and symbol.');let result=await register(f.fullName.value.trim(),f.email.value.trim(),f.password.value);location.assign(result.preview?'dashboard.html':'confirm-account.html?email='+encodeURIComponent(f.email.value.trim()));break;
 case 'confirmForm':await confirmAccount(f.email.value.trim(),f.verifyCode.value.trim());toast(isDemo()?'Preview confirmation complete.':'Email verified successfully!');location.assign('login.html?email='+encodeURIComponent(f.email.value.trim()));break;
 case 'forgotForm':await requestPasswordReset(f.email.value.trim());toast(isDemo()?'Preview mode: no recovery email was sent.':'If eligible, a recovery code has been requested.');location.assign('reset-password.html?email='+encodeURIComponent(f.email.value.trim()));break;
 case 'resetForm':if(!isDemo()&&!isStrong(f.password.value))throw Error('Choose a stronger password (12+ characters, upper/lowercase, number and symbol).');await completePasswordReset(f.email.value.trim(),f.verifyCode.value.trim(),f.password.value);toast(isDemo()?'Preview recovery complete.':'Your password has been updated.');location.assign('login.html?email='+encodeURIComponent(f.email.value.trim()));break;
 case 'listingForm':{
 let file=photoFile;if(file&&!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Upload a JPG, PNG or WebP photo.');if(file&&file.size>5242880)throw Error('Maximum photo size is 5 MB.');
 let extra=[];if(f.preparedOn.value)extra.push('Prepared on: '+f.preparedOn.value);if(f.pickupWindow.value.trim())extra.push('Pickup window: '+f.pickupWindow.value.trim());if(f.dietary.value.trim())extra.push('Dietary: '+f.dietary.value.trim());
 let description=f.description.value.trim()+(extra.length?'\n\n--- Pickup details ---\n'+extra.join('\n'):'');if(description.length>2000)throw Error('The description and additional details must total under 2,000 characters.');
 let cutoff=new Date(f.expiryTime.value);if(isNaN(cutoff.getTime())||cutoff.getTime()<=Date.now())throw Error('Select a future collection deadline.');
 const payload={foodName:f.foodName.value.trim(),category:f.category.value,description,quantity:f.quantity.value.trim(),location:f.location.value.trim(),expiryTime:cutoff.toISOString(),allergyInfo:f.allergyInfo.value.trim(),storageInstructions:f.storageInstructions.value.trim()};
 await createListing(payload,file);toast(isDemo()?'Preview listing added in this browser.':'Your listing is live.');location.assign('my-listings.html');break;
 }
 case 'messageDonorForm':if(!session){location.assign('login.html?next='+encodeURIComponent(location.pathname.split('/').pop()+location.search));return;}if(!selectedListing?.ownerUserId)throw Error('This listing has no available donor identifier.');let text=f.hello.value.trim();if(!text)throw Error('Write a message first.');await sendMessage({listingId:selectedListing.listingId,toUserId:selectedListing.ownerUserId,text});toast(isDemo()?'Preview message saved locally.':'Message delivered to ShareBite inbox.');location.assign('messages.html');break;
 case 'ratingForm':if(!score)throw Error('Choose between 1 and 5 stars.');await addRating(selectedListing.listingId,score);toast(isDemo()?'Preview rating saved locally.':'Rating recorded.');location.reload();break;
 case 'threadSendForm':{let msg=f.chatText.value.trim(),th=allThreads.find(t=>t.threadId===selectedThread);if(!th)throw Error('Choose a thread first.');await sendMessage({listingId:th.listingId,toUserId:th.peerUserId,text:msg});f.reset();allThreads=await getInbox();await openThread(selectedThread);break;}
 }
 }catch(err){if(authPages.includes(page))authError(err.message);else{let box=document.getElementById('listingError');if(box&&page==='add-food')box.innerHTML=notice(err.message,'error');else toast(err.message,true);} }finally{if(btn)btn.disabled=false;}}
document.addEventListener('submit',formSubmit);
document.addEventListener('input',ev=>{if(page==='browse'&&ev.target.id==='foodSearch')drawBrowse()});
document.addEventListener('change',async ev=>{if(page==='browse'&&['foodCategory','foodSort'].includes(ev.target.id))drawBrowse();if(['photo','photoGallery'].includes(ev.target.id)){let file=ev.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5242880){ev.target.value='';toast('Use JPG, PNG or WebP no larger than 5 MB.',true);return;}photoFile=file;document.getElementById('photoImg').src=URL.createObjectURL(file);document.getElementById('photoPreview').classList.add('show');}if(ev.target.matches('.status-select')&&ev.target.value){const orig=ev.target.value;ev.target.disabled=true;try{await updateListing(ev.target.dataset.id,orig);toast('Listing updated.');await myFood();}catch(err){toast(err.message,true);ev.target.disabled=false;}}});
document.addEventListener('click',async ev=>{let pass=ev.target.closest('[data-password]');if(pass){let input=document.getElementById(pass.dataset.password);input.type=input.type==='password'?'text':'password';pass.textContent=input.type==='password'?'Show':'Hide';}let star=ev.target.closest('[data-score]');if(star){score=Number(star.dataset.score);document.querySelectorAll('[data-score]').forEach(s=>s.classList.toggle('selected',Number(s.dataset.score)<=score));}let t=ev.target.closest('[data-thread]');if(t)openThread(t.dataset.thread);if(ev.target.id==='resendBtn'){let email=document.getElementById('email').value.trim();if(!email)return authError('Enter your email before requesting a new code.');try{await resendConfirmation(email);authError(isDemo()?'Preview only: no code sent.':'A new confirmation code was requested.','success');}catch(err){authError(err.message);}}});
async function main(){try{if(!isDemo()){const c=window.SHAREBITE_CONFIG;if(!c.apiBaseUrl||!c.userPoolId||!c.userPoolClientId)throw Error('Live mode is selected but CloudFormation Outputs have not been added to js/config.js.');}try{session=await currentSession();}catch(err){if(internalPages.includes(page))throw err;console.warn(err);}if(internalPages.includes(page)&&!session){await requireSession(location.pathname.split('/').pop()+location.search);return;}
 if(page==='home')home();else if(page==='browse')await browse();else if(page==='food-details')await details();else if(page==='add-food')addFood();else if(page==='dashboard')await dashboard();else if(page==='my-listings')await myFood();else if(page==='messages')await messages();else if(page==='profile')await profile();else if(authPages.includes(page))authPage();else if(['how-it-works','privacy','faq'].includes(page))infoPage(page);else home();
 }catch(err){console.error(err);shell(pageHero('Configuration check','A quick <span class="serif-italic">connection check.</span>',e(err.message),`<a href="index.html" class="btn btn-primary">Return home</a>`)+`<section class="container" style="padding:45px 0">${notice('See connection-check.html for the exact CloudFormation Outputs and CORS instructions.','info')}</section>`);}}
main();

// 3-D perspective follows the pointer gently, only on precision devices and without reduced-motion preference.
function initStudioMotion(){if(!window.matchMedia||!matchMedia('(pointer:fine)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let stage=document.querySelector('.hero-stage');if(!stage)return;let frame=0;stage.addEventListener('pointermove',event=>{cancelAnimationFrame(frame);let rect=stage.getBoundingClientRect();let xx=(event.clientX-rect.left)/rect.width-.5,yy=(event.clientY-rect.top)/rect.height-.5;frame=requestAnimationFrame(()=>{stage.style.transform=`perspective(1100px) rotateY(${xx*9}deg) rotateX(${-yy*7}deg) translateY(-5px)`});});stage.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);stage.style.transform='';});}
window.addEventListener('load',()=>setTimeout(initStudioMotion,100));
